/**
 * 从视频流中提取指定帧的时间戳
 * @param video_stream 视频数据流指针
 * @param stream_size 视频流总大小
 * @param frame_index 要提取时间戳的帧索引
 * @param frame_size 每帧的大小
 * @return 时间戳值，如果参数无效则返回-1
 */
long extract_timestamp(unsigned char* video_stream, int stream_size, int frame_index, int frame_size) {
    // 参数验证
    if (video_stream == NULL || frame_size <= 0 || frame_index < 0) {
        return -1;
    }

    // 计算帧在流中的偏移位置
    long frame_offset = (long)frame_index * frame_size;

    // 检查是否超出流的边界
    if (frame_offset + frame_size > stream_size) {
        return -1;
    }

    // 假设时间戳存储在每帧的固定偏移位置（例如：帧头的第8-15字节）
    // 这里假设时间戳占用8个字节，以小端序存储
    int timestamp_offset = 8; // 时间戳在帧内的偏移位置

    // 确保时间戳偏移不会超出帧边界
    if (timestamp_offset + sizeof(long) > frame_size) {
        return -1;
    }

    // 计算时间戳在视频流中的绝对位置
    unsigned char* timestamp_ptr = video_stream + frame_offset + timestamp_offset;

    // 从内存中读取8字节的时间戳值（小端序）
    long timestamp = 0;
    for (int i = 0; i < sizeof(long); i++) {
        timestamp |= ((long)timestamp_ptr[i]) << (i * 8);
    }

    return timestamp;
}
